/**
 * The authoritative per-provider factual model registry: every model
 * local-router knows to be available upstream, free AND paid, with
 * capability hints and source URLs. Compiled 2026-08-20/21 from live
 * provider /models endpoints (captured verbatim), official provider docs,
 * and models.dev. Live /v1/models refreshes layer actual upstream truth
 * on top per provider; this registry seeds the toggle store at boot so
 * every known model is togglable even before the first refresh.
 *
 * Primary sources per provider:
 * - wafer-serverless: https://pass.wafer.ai/v1/models (live)
 * - zenmux: https://zenmux.ai/api/v1/models (live, 164)
 * - kilo: https://api.kilo.ai/api/gateway/models (live, 367; public)
 * - nous-portal: https://inference-api.nousresearch.com/v1/models (live, 373; public)
 * - pioneer: https://api.pioneer.ai/v1/models (live, 166; public)
 * - commandcode: https://api.commandcode.ai/provider/v1/models (live, 58; public)
 * - nvidia-nim: https://integrate.api.nvidia.com/v1/models (live, 102; specs partial)
 * - zai: coding-plan /models (live w/ key; specs from docs.z.ai model pages)
 * - cline: NO models API (404 verified) — curated chat-proven set + docs examples
 * - moonshot: https://platform.kimi.ai/docs/models
 * - xiaomi-mimo: https://mimo.mi.com/docs (Token Plan: all 6 models, all tiers)
 * - nebius: models.dev + tokenfactory deprecation notices
 * - modal / modal-proxy: models.dev + modal.com/docs/guide/endpoint-integrations
 * - opencode-go / opencode-zen: live /v1/models (public) + docs.opencode.ai pricing
 * - github-copilot: docs.github.com supported-models reference (plan-gated)
 * - antigravity: ai.google.dev Gemini API models + pricing pages
 *
 * Registry entries are discovery metadata only — serving still requires a
 * valid provider key, and capabilities are hints that
 * mapLiveRawModelsToCatalog applies when the id is not already in the
 * curated toggle store.
 */

export interface RegistryModelEntry {
  id: string;
  contextLength?: number;
  outputTokens?: number;
  supportsTools?: boolean;
  supportsImages?: boolean;
  supportsCache?: boolean;
  supportsReasoning?: boolean;
  /** Factual availability tier from provider docs (free | paid | subscription). */
  tier?: 'free' | 'paid' | 'subscription';
  /** Where this entry's facts came from (docs page / models endpoint). */
  sourceUrl?: string;
  note?: string;
}

/**
 * Providers whose upstream exposes no OpenAI-compatible /models list.
 * (zai HAS one — verified live 2026-08-21 — and was removed from this set.)
 */
export const PROVIDERS_WITHOUT_LIVE_MODEL_LIST: readonly string[] = ['cline'];

